  const { mergeFilters } = await import(`${W}/lib/search/merge.ts`);
  const { parseQueryParam } = await import(`${W}/lib/search/params.ts`);
  const { GET } = await import(`${W}/app/api/candidates/search/route.ts`);
  const j = (x: unknown) => JSON.stringify(x);
  const show = (n: number | string, x: unknown) => console.log(`#${n}`, j(x));

  show(1, ['usa', 'Brasil', 'canada', 'Atlantis', 'Other'].map(canonicalCountry));
  show(2, findCountries('React dev in Canada or the UK'));
  show(3, [findCountries('Indiana plus us'), findCountries('based in the US')]);
  const rq = (q: string) => {
    const p = parseQueryWithRules(q);
    return { ...p.filters, seniority: p.seniority, keywords: p.keywords, searchText: p.searchText, source: p.source };
  };
  const rules = [
    'Senior React engineer in Canada under 130k',
    'Rust developer with 5+ years experience in AI/ML',
    'python data engineer, max $8k/month, Brazil',
    'backend between 60k and 90k',
    'java 3-6 years',
    'junior frontend',
    'senior with 2+ years',
    'fintech payments',
    'under 5 years of go',
    '100-130k react',
  ];
  rules.forEach((q, i) => show(4 + i, rq(q)));
  const base = { skills: [], countries: [], minYears: null, maxYears: null, minSalary: null, maxSalary: null, seniority: null, keywords: [], searchText: '' };
  show(14, normalizeParsed({ ...base, skills: ['reactjs', 'Kubernetes', 'fintech'] }, 'llm'));
  show(15, normalizeParsed({ ...base, countries: ['usa', 'atlantis'] }, 'llm').filters.countries);
  show(16, normalizeParsed({ ...base, minSalary: 150000, maxSalary: 90000, minYears: -1 }, 'llm').filters);
  show('17a', normalizeParsed({ ...base, seniority: 'lead' }, 'llm').filters);
  show('17b', normalizeParsed({ ...base, seniority: 'lead', maxYears: 4 }, 'llm').filters);
  show(18, normalizeParsed({ ...base, skills: ['React'], keywords: ['React', 'fintech', 'Fintech', ' '] }, 'llm').keywords);
  show(19, await parseQuery(''));
  const q4 = 'Senior React engineer in Canada under 130k';
  const good = async () => j({ ...base, skills: ['React'], countries: ['Canada'], maxSalary: 130000, seniority: 'senior', searchText: 'Senior React engineer' });
  show(20, await parseQuery(q4, { complete: good }));
  show(21, await parseQuery(q4, { complete: async () => { throw new Error('x'); } }));
  show(22, (await parseQuery(q4, { complete: async () => 'not json' }))?.source);
  let calls = 0;
  const counting = async () => { calls++; return good(); };
  await parseQuery('Senior React', { complete: counting });
  await parseQuery('  senior REACT ', { complete: counting });
  show(23, { calls });
  const E = { countries: [], skills: [], minYears: null, maxYears: null, minSalary: null, maxSalary: null };
  show(24, mergeFilters({ ...E, countries: ['Brazil'] }, { ...E, countries: ['Canada'], maxSalary: 130000 }));
  show(25, mergeFilters(E, { ...E, skills: ['React'], minYears: 5 }).fromQuery);
  show('pq', [parseQueryParam(new URLSearchParams('q=%20%20')), parseQueryParam(new URLSearchParams('')), parseQueryParam(new URLSearchParams('q=%20x%20'))]);
  const get = async (qs: string) => {
    const res = await GET(new Request(`http://localhost/api/candidates/search?${qs}`));
    const body = await res.json();
    return { status: res.status, query: body.query, interpretation: body.interpretation, relaxed: body.relaxed, filters: body.filters, total: body.total, keys: Object.keys(body) };
  };
  show(26, await get('q=Rust%20developer%20with%205%2B%20years'));
  show(27, await get('q=%20%20'));
  show(28, await get('q=react&skill=Python'));
  show('400', await get('minYears=abc'));
}
main();

